"""
Core Concept: Extracting data using logical conditions instead of numeric indices.
This is the NumPy equivalent of a SQL 'WHERE' clause. 
You will use this constantly to filter out bad data, outliers, or specific targets.
"""

import numpy as np

# ==========================================
# 1. CREATING BOOLEAN MASKS
# A mask is simply an array of True/False values generated by a condition.
# ==========================================
print("--- 1. Boolean Masks ---")
arr = np.array([10, 15, 20, 25, 30, 35, 40])
print(f"Original Array: {arr}")

# Which numbers are greater than 20?
# This doesn't return the numbers! It returns a mask of True/False.
mask = arr > 20
print(f"Mask (arr > 20): {mask}")
print("-" * 40)


# ==========================================
# 2. APPLYING THE MASK (Filtering)
# You pass the True/False mask directly into the brackets [] of the array.
# NumPy will only return the elements where the mask is True.
# ==========================================
print("\n--- 2. Filtering with Masks ---")

# Step-by-step
filtered_arr = arr[mask]
print(f"Filtered Array (using the mask variable): {filtered_arr}")

# The professional way (all in one line)
print(f"Filtered Array (one-liner): {arr[arr > 20]}")
print("-" * 40)


# ==========================================
# 3. MULTIPLE CONDITIONS (Bitwise Operators)
# CRITICAL: You CANNOT use the Python words 'and' or 'or'. 
# You MUST use bitwise operators: & (AND), | (OR), ~ (NOT).
# You MUST wrap each individual condition in parentheses ().
# ==========================================
print("\n--- 3. Multiple Logical Conditions ---")
sales = np.array([150, 500, 250, 800, 1200, 300, 950])
print(f"Sales Data: {sales}")

# AND (&): Sales between 300 and 1000
mid_tier_sales = sales[(sales >= 300) & (sales <= 1000)]
print(f"Mid-tier sales (300 to 1000): {mid_tier_sales}")

# OR (|): Sales either very low (under 200) OR very high (over 1000)
extreme_sales = sales[(sales < 200) | (sales > 1000)]
print(f"Extreme sales (< 200 or > 1000): {extreme_sales}")

# NOT (~): Sales that are NOT exactly 500
not_500 = sales[~(sales == 500)]
print(f"Sales excluding 500: {not_500}")
print("-" * 40)


# ==========================================
# 4. FILTERING AND ASSIGNING (Data Cleaning)
# You can use boolean indexing to overwrite specific values instantly.
# ==========================================
print("\n--- 4. Overwriting Data based on Conditions ---")
sensor_data = np.array([22.5, 23.1, -999.0, 22.8, -999.0, 24.0])
print(f"Raw Sensor Data: {sensor_data}")

# -999.0 is clearly an error code from a broken sensor. 
# Let's replace all error codes with a neutral 0.0 (or np.nan)
sensor_data[sensor_data == -999.0] = 0.0

print(f"Cleaned Sensor Data: {sensor_data}")
